"""Shared helpers for the eval scripts: write eval/results.md and clean text."""

import os
import re
from pathlib import Path

RESULTS_PATH = Path(__file__).resolve().parent / "results.md"

HEADER = (
    "# Evaluation results\n\n"
    "Generated by the scripts in eval/. Each script replaces only its own section.\n"
)

# Gemini keys start with "AIza", Groq keys with "gsk_".
KEY_PATTERN = re.compile(r"AIza[0-9A-Za-z_\-]{20,}|gsk_[0-9A-Za-z]{20,}")


def clean(text, limit=200):
    """Shorten text for results.md, remove anything that looks like an API key,
    and make it safe inside a Markdown table cell."""
    text = str(text)
    for name in ("GEMINI_API_KEY", "GROQ_API_KEY"):
        value = os.environ.get(name)
        if value:
            text = text.replace(value, "[REDACTED]")
    text = KEY_PATTERN.sub("[REDACTED]", text)
    text = " ".join(text.split()).replace("|", "\\|")
    return text if len(text) <= limit else text[:limit - 1] + "…"


def write_section(name, body):
    """Replace this script's section in results.md, keeping the others."""
    begin, end = f"<!-- BEGIN {name} -->", f"<!-- END {name} -->"
    block = f"{begin}\n{body.strip()}\n{end}"

    text = RESULTS_PATH.read_text(encoding="utf-8") if RESULTS_PATH.exists() else HEADER

    if begin in text and end in text:
        before = text[:text.index(begin)]
        after = text[text.index(end) + len(end):]
        text = before + block + after
    else:
        text = text.rstrip() + "\n\n" + block + "\n"

    RESULTS_PATH.write_text(text, encoding="utf-8")
